<template>
 <div class="teaching-overview">
  <section class="overview-workbench" aria-label="教学工作台">
   <div class="workbench-main workbench-welcome"><div class="welcome-copy"><span class="workbench-label">欢迎回到教学工作台</span><h2>{{greeting}}，老师。</h2><p>{{welcome.description}}</p><div class="welcome-footer"><RouterLink class="welcome-action primary" :to="welcome.to"><svg class="welcome-action-icon" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2h-2"/><rect x="8" y="2" width="8" height="4" rx="1"/><path d="M8 11h8M8 15h5"/></svg>{{welcome.action}}</RouterLink><div class="welcome-status"><strong>{{summary.pendingReviewTotal||0}}<span> 份</span></strong><span>待点评报告</span></div></div></div><img class="welcome-illustration" :src="greetingArtwork" alt="" aria-hidden="true" width="200" height="160"/></div>
   <div class="workbench-next"><header class="workbench-section-head"><h3>近期教学安排</h3><RouterLink :to="link('/teacher/tasks')">全部任务 ↗</RouterLink></header><template v-if="active.length"><div class="next-task-heading"><span class="next-task-status">进行中</span><RouterLink class="workbench-task-title" :to="link('/teacher/tasks/'+active[0].id)">{{active[0].title}}</RouterLink></div><dl class="next-task-facts"><div><dt>教学班级</dt><dd>{{active[0].className}}</dd></div><div><dt>截止时间</dt><dd>{{active[0].deadline.slice(0,10)}} {{active[0].deadline.slice(11,16)}}</dd></div><div><dt>训练要求</dt><dd>每人 {{active[0].minAttempts}} 次有效训练</dd></div></dl><div class="next-task-result"><strong>{{taskCounts(active[0])[0]}} 人已完成</strong><span>{{taskCounts(active[0])[1]+taskCounts(active[0])[2]}} 人待完成</span><RouterLink :to="link('/teacher/tasks/'+active[0].id)">查看执行明细 →</RouterLink></div><small>完成按有效训练次数统计，能力表现请查看报告。</small></template><div v-else class="next-task-empty"><h4>暂时没有进行中的任务</h4><p>选择教学班级，设置问题与评价目标，发布下一项训练。</p><RouterLink :to="link('/teacher/tasks/create')">创建训练任务 →</RouterLink></div></div>
   <div class="workbench-todos"><header class="workbench-section-head"><h3>教学跟进</h3><span>全部所带班级</span></header><RouterLink v-for="(item,index) in followups" :key="item.title" class="followup-row" :to="item.to"><span class="followup-artwork" :style="{backgroundPosition:(index*50)+'% center'}" aria-hidden="true"/><span class="followup-copy"><strong>{{item.title}}</strong><small>{{item.description}}</small></span><span class="followup-state" :class="{pending:item.count>0}">{{item.count>0?item.count+item.unit:'已清'}}<span aria-hidden="true"> →</span></span></RouterLink></div>
  </section>
  <section class="overview-filter-bar" aria-label="教学统计筛选"><form class="overview-filters" @submit.prevent>
   <label>学期<select v-model="semester"><option value="">全部学期</option><option v-for="s in semesters" :key="s">{{s}}</option></select></label>
   <label>班级<select v-model="classId" aria-label="筛选教学班级"><option value="">全部班级</option><option v-for="c in eligibleClasses" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label>
   <label>岗位<select v-model="job" aria-label="总览训练岗位"><option value="">全部岗位</option><option v-for="j in jobs" :key="j.id" :value="String(j.id)">{{j.name}}</option></select></label>
   <label>时间<select v-model.number="period" aria-label="总览训练周期"><option :value="7">近7天</option><option :value="30">近30天</option><option :value="90">近90天</option></select></label>
   <RouterLink class="primary" :to="link('/teacher/tasks/create')">发布训练任务</RouterLink>
  </form>
  <p class="overview-scope">{{from}} ～ {{today}} · 训练统计仅包含教师可访问的教学记录；任务执行截至当前。</p>
  </section>
  <section class="overview-summary-details" aria-label="教学摘要"><div class="overview-summary-list"><RouterLink v-for="m in metrics" :key="m.label" :to="m.global?link(m.path,{classId:undefined,classIds:undefined,semester:undefined,jobId:undefined,period:'all'}):link(m.path)"><span>{{m.label}}</span><strong>{{m.value}} {{m.unit}}</strong><small>{{m.note}}</small></RouterLink></div></section>
  <section v-if="reportLoadError" class="notice error" role="alert"><p>部分报告读取失败，执行进度仍可查看；能力分析可能不完整。</p><button @click="$emit('reload')">重新读取报告</button></section>

  <div class="overview-analysis-heading"><div><h2>任务进度与学生跟进</h2><p>先查看当前任务，再跟进未完成任务较多的学生。</p></div><RouterLink :to="link('/teacher/tasks')">进入任务工作台</RouterLink></div>
  <div class="overview-analysis-grid"><div class="overview-analysis-column"><section class="live-panel overview-tasks"><header><div><h2>进行中的训练任务</h2><p class="section-subtitle">最近截止的 5 项任务 · 共 {{activeTaskTotal}} 项进行中</p></div><RouterLink :to="link('/teacher/tasks')">全部任务 ↗</RouterLink></header><div v-if="active.length" class="overview-task-table"><table><thead><tr><th>任务 / 班级</th><th>截止日期</th><th>执行情况</th><th>操作</th></tr></thead><tbody><tr v-for="t in active" :key="t.id"><td><RouterLink :to="link('/teacher/tasks/'+t.id)">{{t.title}}</RouterLink><small>{{t.className}}</small></td><td>{{t.deadline.slice(5,10)}}<small>{{t.deadline.slice(11,16)}}</small></td><td><strong>{{taskCounts(t)[0]}} 人完成</strong><small>{{taskCounts(t)[1]+taskCounts(t)[2]}} 人待完成 · {{taskCounts(t)[2]}} 人未开始</small><small class="backlog-late" v-if="(t.assignments||[]).some(a=>isOverdue(a,t))">{{(t.assignments||[]).filter(a=>isOverdue(a,t)).length}} 人已逾期</small></td><td><RouterLink :to="link('/teacher/tasks/'+t.id)">跟进 →</RouterLink></td></tr></tbody></table></div><div v-else class="overview-guidance"><strong>还没有进行中的任务</strong><p>选择教学班级并发布训练，学生提交后即可跟进执行与反馈。</p><RouterLink class="primary" :to="link('/teacher/tasks/create')">发布训练任务</RouterLink></div></section><section class="live-panel"><header><div><h2>训练参与与提交</h2><p class="section-subtitle">按日观察有效训练量与参与人数</p></div><RouterLink :to="link('/teacher/training-records')">查看训练明细 →</RouterLink></header><OverviewTrainingChart :points="trend" @select="openDay"/><p class="overview-insight">当前范围内，<strong>{{trained}}名当前成员</strong>参与训练，产生<strong>{{valid.length}}条有效记录</strong>；参与率 {{students.length?format(pct(trained,students.length))+'%':'—'}}。</p></section></div><div class="overview-analysis-column"><section class="live-panel overview-backlog"><header><div><h2>学生未完成任务</h2><p class="section-subtitle">按未完成任务数排序，优先跟进任务积压</p></div></header><label class="backlog-filter">查看范围<select v-model.number="backlogMinimum" aria-label="未完成任务数量筛选"><option :value="1">全部未完成学生</option><option :value="3">积压 3 项及以上</option></select></label><p class="chart-caption">当前班级与岗位下已开放且未结束的任务，不受训练统计周期限制；排除已完成与减免。</p><div class="backlog-students"><article v-for="student in visibleBacklog" :key="student.id" class="backlog-student"><div class="backlog-student-heading"><RouterLink :to="link('/teacher/students/'+student.id)">{{student.name}}</RouterLink><span :class="{'backlog-heavy':student.tasks.length>=3}">{{student.tasks.length}} 项未完成</span></div><p>{{student.overdue?student.overdue+' 项已逾期':'暂无逾期任务'}}<span v-if="student.tasks.length>=3"> · 任务积压较多</span></p><ul><li v-for="row in student.tasks" :key="row.task.id"><RouterLink :to="link('/teacher/tasks/'+row.task.id,{assignmentId:row.assignment.id,execution:'unfinished'})">{{row.task.title}}</RouterLink><span :class="{'backlog-late':row.overdue}">{{row.overdue?'已逾期':'截止 '+row.task.deadline.slice(5,10)}}</span></li></ul></article></div><div v-if="!visibleBacklog.length" class="overview-guidance"><strong>{{backlogMinimum===3?'暂无积压 3 项及以上的学生':'当前没有未完成任务的学生'}}</strong><p>学生的任务分配与完成状态更新后，名单会同步变化。</p></div></section><section class="live-panel"><header><div><h2>任务执行状态</h2><p class="section-subtitle">区分完成要求、训练中与尚未开始</p></div><RouterLink :to="link('/teacher/tasks')">查看任务 →</RouterLink></header><p class="chart-caption">截至当前，按分配人次统计，排除减免；完成次数要求不代表能力达标。</p><TeachingPieChart :items="distribution" donut :selected="execution" @select="execution=$event"/><div v-if="execution" class="overview-drilldown" aria-live="polite"><h3>{{distribution.find(d=>d.key===execution)?.label}} · {{executionRows.length}} 人次</h3><RouterLink v-for="a in executionRows.slice(0,5)" :key="a.id" :to="link('/teacher/tasks/'+a.task.id,{assignmentId:a.id,execution})">{{a.name}} · {{a.task.title}} →</RouterLink><p v-if="executionRows.length>5">仅显示前5条，请进入任务查看完整名单。</p><button @click="execution=''">清除状态选择</button></div></section></div></div>
 </div>
</template>
<script setup>
import {computed,ref,watch,onMounted,onUnmounted} from 'vue'
import greetingArtwork from '../../assets/generated/teacher-welcome-border.png'
import {useRoute,useRouter} from 'vue-router'
import {taskBacklog} from '../../services/taskBacklog.js'
import {isOverdue} from '../../services/teachingWorkspace.js'
import OverviewTrainingChart from './OverviewTrainingChart.vue'
import TeachingPieChart from './TeachingPieChart.vue'
import {stamp,dayKey,pct,allocations} from '../../services/teachingAnalysis.js'
import '../../assets/styles/teaching-overview.css'
const props=defineProps({classes:Array,tasks:Array,reports:Array,people:Array,summary:Object,reportLoadError:Boolean});defineEmits(['reload'])
const route=useRoute(),router=useRouter(),semester=ref(String(route.query.semester||'')),classId=ref(String(route.query.classId||'')),job=ref(String(route.query.jobId||'')),period=ref([7,30,90].includes(Number(route.query.period))?Number(route.query.period):30)
const colors=['#10b981','#9ddfc3','#e4e4e7'],semesters=computed(()=>[...new Set(props.classes.map(c=>c.semester).filter(Boolean))]),eligibleClasses=computed(()=>props.classes.filter(c=>!semester.value||c.semester===semester.value)),classIds=computed(()=>eligibleClasses.value.filter(c=>!classId.value||String(c.id)===classId.value).map(c=>c.id)),scopedTasks=computed(()=>props.tasks.filter(t=>classIds.value.includes(t.classId)&&(!job.value||String(t.jobId)===job.value))),jobs=computed(()=>[...new Map(props.tasks.map(t=>[t.jobId,{id:t.jobId,name:t.jobName}])).values()])
const students=computed(()=>[...new Map(props.people.filter(s=>classIds.value.includes(s.classId)).map(s=>[s.id,{...s,classNames:props.people.filter(p=>p.id===s.id&&classIds.value.includes(p.classId)).map(p=>p.className).join('、')}])).values()]),today=dayKey(Date.now()),from=computed(()=>dayKey(Date.now()-(period.value-1)*86400000)),rows=computed(()=>props.reports.filter(r=>scopedTasks.value.some(t=>t.id===r.taskId)&&r.submittedAt&&dayKey(stamp(r.submittedAt))>=from.value&&stamp(r.submittedAt)<=Date.now())),valid=computed(()=>rows.value.filter(r=>r.state==='READY')),trained=computed(()=>new Set(valid.value.filter(r=>students.value.some(s=>s.id===r.studentId)).map(r=>r.studentId)).size),assigned=computed(()=>allocations(scopedTasks.value)),done=computed(()=>assigned.value.filter(a=>a.completionStatus==='COMPLETED').length)
const metrics=computed(()=>[{label:'学生总数',value:students.value.length,unit:'人',note:'当前范围已加入成员，跨班级去重',path:'/teacher/students',action:'学生管理'},{label:'训练活跃度',value:trained.value+' / '+format(pct(trained.value,students.value.length))+'%',note:'当前周期有有效教学训练的成员',path:'/teacher/activity',action:'查看活跃情况'},{label:'训练次数',value:valid.value.length,unit:'次',note:'当前周期有效教学训练记录',path:'/teacher/training-records',action:'查看训练明细'},{label:'次数要求完成率',value:assigned.value.length?format(pct(done.value,assigned.value.length))+'%':'—',note:done.value+' / '+assigned.value.length+' 人次 · 当前范围全部任务',path:'/teacher/tasks',action:'任务完成报告'},{label:'任务积压学生',value:backlog.value.filter(s=>s.tasks.length>=3).length,unit:'人',note:'有 3 项及以上未完成任务',path:'/teacher/tasks',action:'查看未完成任务'},{label:'待点评报告',value:props.summary.pendingReviewTotal||0,unit:'份',note:'所带班级全局待办',path:'/teacher/reviews',action:'去点评',global:true}])
const trend=computed(()=>Array.from({length:period.value},(_,i)=>{const date=dayKey(Date.now()-(period.value-1-i)*86400000),own=valid.value.filter(r=>dayKey(stamp(r.submittedAt))===date);return {date,count:own.length,active:new Set(own.map(r=>r.studentId)).size}})) ,active=computed(()=>scopedTasks.value.filter(t=>t.lifecycle==='ACTIVE').sort((a,b)=>stamp(a.deadline)-stamp(b.deadline)).slice(0,5)),overdue=computed(()=>allocations(props.tasks).filter(a=>isOverdue(a,a.task)))
const activeTaskTotal=computed(()=>scopedTasks.value.filter(t=>t.lifecycle==='ACTIVE').length)
const execution=ref(''),distribution=computed(()=>[{key:'COMPLETED',label:'已完成次数要求',color:'#34d399'},{key:'IN_PROGRESS',label:'尚未完成要求',color:'#a7e5ce'},{key:'PENDING_VALIDATION',label:'报告校验中',color:'#f8ce8b'},{key:'NOT_STARTED',label:'未开始',color:'#d4d4d8'}].map(d=>({...d,count:assigned.value.filter(a=>a.completionStatus===d.key).length}))),executionRows=computed(()=>assigned.value.filter(a=>a.completionStatus===execution.value))
const clock=ref(Date.now());let greetingTimer
onMounted(()=>{greetingTimer=setInterval(()=>clock.value=Date.now(),60000)})
onUnmounted(()=>clearInterval(greetingTimer))
const greeting=computed(()=>{const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',hourCycle:'h23'}).format(clock.value));return hour<6?'夜深了':hour<12?'上午好':hour<18?'下午好':'晚上好'})
const welcome=computed(()=>{if(props.summary.pendingReviewTotal>0)return {description:'从一份学生报告开始，用具体的反馈帮助学生找到下一步练习方向。',action:'去点评报告',to:link('/teacher/reviews',{classId:undefined,classIds:undefined,semester:undefined,jobId:undefined,period:'all'})};if(overdue.value.length)return {description:'有学生尚未完成训练要求。查看任务进度，了解他们需要哪些帮助。',action:'跟进训练进度',to:{path:'/teacher/tasks',query:{view:'completion',returnTo:route.fullPath}}};if(props.classes.some(c=>c.pendingCount>0))return {description:'有学生正在等待加入教学班。确认申请，帮助他们开始新的训练。',action:'审核加入申请',to:{path:'/teacher/classes'}};if(active.value.length)return {description:'教学安排正在推进。看看最近的训练任务，继续陪伴学生积累与进步。',action:'查看当前任务',to:link('/teacher/tasks/'+active.value[0].id)};return {description:'准备一项有明确目标的训练，让学生从下一次练习中获得具体收获。',action:'发布训练任务',to:link('/teacher/tasks/create')}})
const followups=computed(()=>[{title:'报告反馈',count:props.summary.pendingReviewTotal||0,unit:'份',description:props.summary.pendingReviewTotal?'结合回答依据，给出具体改进建议':'当前没有待点评报告，可查看已有反馈',to:link('/teacher/reviews',{classId:undefined,classIds:undefined,semester:undefined,jobId:undefined,period:'all'})},{title:'训练跟进',count:overdue.value.length,unit:'人次',description:overdue.value.length?'查看逾期原因与学生训练记录':'当前没有逾期未完成分配',to:{path:'/teacher/tasks',query:{view:'completion',returnTo:route.fullPath}}},{title:'成员审核',count:props.classes.reduce((n,c)=>n+(c.pendingCount||0),0),unit:'条',description:props.classes.some(c=>c.pendingCount>0)?'确认学生身份，完成教学班加入审核':'当前没有待审核申请，可管理班级成员',to:{path:'/teacher/classes'}}])
const backlogMinimum=ref(1),backlog=computed(()=>taskBacklog(scopedTasks.value)),visibleBacklog=computed(()=>backlog.value.filter(s=>s.tasks.length>=backlogMinimum.value))
function taskCounts(t){const a=(t.assignments||[]).filter(a=>!a.exempt);return [a.filter(a=>a.completionStatus==='COMPLETED').length,a.filter(a=>!['COMPLETED','NOT_STARTED'].includes(a.completionStatus)).length,a.filter(a=>a.completionStatus==='NOT_STARTED').length]}
const format=v=>v==null?'—':Math.round(v)
function link(path,query={}){return {path,query:{classId:classId.value||undefined,classIds:semester.value?classIds.value.join(','):undefined,semester:semester.value||undefined,period:period.value,jobId:job.value||undefined,returnTo:route.path+'?'+new URLSearchParams({classId:classId.value,semester:semester.value,jobId:job.value,period:String(period.value)}),...query}}}
function openDay(date){if(!date)return;router.push(link('/teacher/training-records',{date}))}
watch([semester,classId,job,period],()=>{execution.value='';router.replace({query:{...route.query,semester:semester.value||undefined,classId:classId.value||undefined,jobId:job.value||undefined,period:period.value}})})
watch(semester,()=>{if(!eligibleClasses.value.some(c=>String(c.id)===classId.value))classId.value=''})
</script>
